				h_set_event = 1;
				h_next_pc = rvfi_pc_rdata[h_i*`RISCV_FORMAL_XLEN +: `RISCV_FORMAL_XLEN];
			end
		end
	end

	always @(posedge clock) begin
		if (reset) begin
			h_seen_next <= 0;
			h_expect_pc <= {`RISCV_FORMAL_XLEN{1'b0}};
			h_expect_pc_valid <= 0;
			h_have_last_order <= 0;
			h_last_order <= 0;
		end else begin
			if (rvfi_valid[`RISCV_FORMAL_CHANNEL_IDX]) begin
				h_have_last_order <= 1;
				h_last_order <= rvfi_order[64*`RISCV_FORMAL_CHANNEL_IDX +: 64];
			end
			if (h_set_event) begin
				h_seen_next <= 1;
				h_expect_pc <= h_next_pc;
				h_expect_pc_valid <= !rvfi_intr[`RISCV_FORMAL_CHANNEL_IDX];
			end
		end
	end

	always @(posedge clock) begin
		if (!reset) begin
			h_no_spurious_expect_valid: assert(!(checker_inst.expect_pc_valid && !h_seen_next));
			h_expect_valid_matches: assert(checker_inst.expect_pc_valid == h_expect_pc_valid);
			if (h_seen_next) begin
				h_seen_next_implies_order_progress: assert(rvfi_order[64*`RISCV_FORMAL_CHANNEL_IDX +: 64] >= checker_inst.insn_order + 1);
			end
			if (rvfi_valid[`RISCV_FORMAL_CHANNEL_IDX] && $past(!reset) && $past(h_have_last_order) && $past(rvfi_valid[`RISCV_FORMAL_CHANNEL_IDX])) begin
				h_rvfi_order_monotonic: assert(rvfi_order[64*`RISCV_FORMAL_CHANNEL_IDX +: 64] >= $past(rvfi_order[64*`RISCV_FORMAL_CHANNEL_IDX +: 64]));
			end
			if (checker_inst.expect_pc_valid) begin
				h_expect_pc_matches: assert(checker_inst.expect_pc == h_expect_pc);
			end
		end
	end

/// Helper Assertion End
endmodule

