					h_rvfi_order_step_inc: assert(rvfi_order[64*`RISCV_FORMAL_CHANNEL_IDX +: 64] == $past(rvfi_order[64*`RISCV_FORMAL_CHANNEL_IDX +: 64]) + 1);
